import { JSX, SVGProps } from "react"

/**
 * Logo Component
 *
 * Renders the application's logo as an SVG or image.
 *
 * @component
 * @example
 * return (
 *   <SeratekLogo width={120} height={40} alt="My App Logo" />
 * )
 *
 * @param {Object} props - Component props
 * @param {number} [props.width] - Width of the logo (optional)
 * @param {number} [props.height] - Height of the logo (optional)
 * @param {string} [props.alt] - Alternative text for the logo (optional)
 * @returns {JSX.Element} The rendered logo element
 */
const SeratekLogo = (props: SVGProps<SVGSVGElement>): JSX.Element => {
    return (
        <svg width="196" height="63" viewBox="0 0 196 63" fill="none" xmlns="http://www.w3.org/2000/svg" xmlnsXlink="http://www.w3.org/1999/xlink" {...props}>
            <rect width="196" height="63" fill="url(#pattern0_6890_28646)" />
            <defs>
                <pattern id="pattern0_6890_28646" patternContentUnits="objectBoundingBox" width="1" height="1">
                    <use xlinkHref="#image0_6890_28646" transform="matrix(0.00170068 0 0 0.005291 -0.265306 -1.6455)" />
                </pattern>
                <image id="image0_6890_28646" width="1280" height="815" preserveAspectRatio="none" xlinkHref="data:image/png;base64," />
            </defs>
        </svg>


    )
}

export default SeratekLogo